package id.belajarsd.app;

import jakarta.validation.Valid; import jakarta.validation.constraints.*;
import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.http.CacheControl;
import org.springframework.http.ResponseEntity;
import java.util.*;
import java.security.SecureRandom;

@RestController @RequestMapping("/api")
public class ApiController {
 private static final SecureRandom QUESTION_RANDOM = new SecureRandom();
 private static final Set<String> CLUB_IDS = Set.of("science", "coding", "literacy", "arts");
 private static final Set<String> ACTIVITY_IDS = Set.of("science:shadow", "science:plants", "science:weather", "coding:sequence", "coding:pattern", "coding:debug", "literacy:headline", "literacy:story", "literacy:reporter", "arts:rhythm", "arts:motif", "arts:soundscape");
 private final SubjectRepository subjects; private final LessonRepository lessons; private final QuestionRepository questions; private final ProgressRepository progress; private final AuthService auth; private final StudentAccountRepository accounts; private final ExtracurricularRecordRepository extracurricularRecords; private final CurriculumMonitorService curriculumMonitor; private final AiQuestionScheduler aiQuestionScheduler;
 public ApiController(SubjectRepository subjects,LessonRepository lessons,QuestionRepository questions,ProgressRepository progress,AuthService auth,StudentAccountRepository accounts,ExtracurricularRecordRepository extracurricularRecords,CurriculumMonitorService curriculumMonitor,AiQuestionScheduler aiQuestionScheduler){this.subjects=subjects;this.lessons=lessons;this.questions=questions;this.progress=progress;this.auth=auth;this.accounts=accounts;this.extracurricularRecords=extracurricularRecords;this.curriculumMonitor=curriculumMonitor;this.aiQuestionScheduler=aiQuestionScheduler;}
 @GetMapping("/health") public Map<String,String> health(){return Map.of("status","ok","application","Teman Belajar SD");}
 @GetMapping("/subjects") public List<Map<String,Object>> getSubjects(@RequestHeader("Authorization") String authorization,@RequestParam(name="grade",required=false) String requestedGrade){String grade=viewGrade(auth.requireSession(bearer(authorization)),requestedGrade);return subjects.findAll().stream().sorted(Comparator.comparing(Subject::getSortOrder)).<Map<String,Object>>map(s->{var m=new LinkedHashMap<String,Object>();m.put("id",s.getId());m.put("name",s.getName());m.put("icon",s.getIcon());m.put("description",s.getDescription());m.put("color",s.getColor());m.put("lessonCount",lessons.findBySubjectIdOrderByIdAsc(s.getId()).stream().filter(l->gradeNumber(l.getGrade()).equals(grade)&&isChapterTitle(l.getTitle())).count());return m;}).toList();}
 @Transactional(readOnly=true) @GetMapping("/subjects/{id}/lessons") public List<Map<String,Object>> getLessons(@PathVariable Long id,@RequestHeader("Authorization") String authorization,@RequestParam(name="grade",required=false) String requestedGrade){String grade=viewGrade(auth.requireSession(bearer(authorization)),requestedGrade);if(!subjects.existsById(id))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Mata pelajaran tidak ditemukan");return lessons.findBySubjectIdWithSubject(id).stream().filter(l->gradeNumber(l.getGrade()).equals(grade)&&isChapterTitle(l.getTitle())).sorted(Comparator.comparingInt((Lesson l)->chapterNumber(l.getTitle())).thenComparing(Lesson::getId)).map(this::lessonDto).toList();}
 @Transactional(readOnly=true) @GetMapping("/lessons/{id}") public Map<String,Object> getLesson(@PathVariable Long id,@RequestHeader("Authorization") String authorization){Lesson l=lessons.findByIdWithSubject(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Materi tidak ditemukan"));requireLessonGrade(l,authorization);return lessonDto(l);}
 @GetMapping("/lessons/{id}/questions") public ResponseEntity<List<Map<String,Object>>> getQuestions(@PathVariable Long id,@RequestHeader("Authorization") String authorization){Lesson lesson=lessons.findByIdWithSubject(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Materi tidak ditemukan"));requireLessonGrade(lesson,authorization);List<Question> bank=new ArrayList<>(questions.findAvailableByLessonId(id,java.time.Instant.now()));Collections.shuffle(bank,QUESTION_RANDOM);List<Map<String,Object>> selected=bank.stream().limit(Math.min(10,bank.size())).<Map<String,Object>>map(q->{var m=new LinkedHashMap<String,Object>();m.put("id",q.getId());m.put("prompt",q.getPrompt());m.put("options",shuffledOptions(q).stream().map(option->ArabicOptionText.render(lesson,option)).toList());return m;}).toList();return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(selected);}
 @Transactional(readOnly=true) @GetMapping("/lessons/{id}/print-questions") public ResponseEntity<Map<String,Object>> getPrintQuestions(@PathVariable Long id,@RequestHeader("Authorization") String authorization){Lesson lesson=lessons.findByIdWithSubject(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Materi tidak ditemukan"));requireLessonGrade(lesson,authorization);List<Map<String,Object>> bank=questions.findAvailableByLessonId(id,java.time.Instant.now()).stream().<Map<String,Object>>map(q->{var m=new LinkedHashMap<String,Object>();m.put("prompt",q.getPrompt());m.put("options",shuffledOptions(q).stream().map(option->ArabicOptionText.render(lesson,option)).toList());return m;}).toList();return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(Map.of("lesson",lessonDto(lesson),"questions",bank));}
 @Transactional @PostMapping("/progress") @ResponseStatus(HttpStatus.CREATED) public Map<String,Object> saveProgress(@RequestHeader("Authorization") String authorization,@Valid @RequestBody ProgressRequest req){StudentAccount account=auth.requireSession(bearer(authorization));if(isAdmin(account))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Latihan akun admin tidak disimpan sebagai progres.");Lesson lesson=lessons.findByIdWithSubject(req.lessonId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Materi tidak ditemukan"));requireLessonGrade(lesson,authorization);if(req.score()>req.total())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Nilai tidak boleh melebihi jumlah soal");Progress p=progress.save(new Progress(accountIdentity(account),lesson,req.score(),req.total()));return progressDto(p);}
 @Transactional(readOnly=true) @GetMapping("/progress") public Map<String,Object> getProgress(@RequestHeader("Authorization") String authorization){String identity=accountIdentity(auth.requireSession(bearer(authorization)));List<Progress> items=progress.findByStudentName(identity);int score=items.stream().mapToInt(Progress::getScore).sum();int total=items.stream().mapToInt(Progress::getTotal).sum();return Map.of("completedQuizzes",items.size(),"averagePercent",total==0?0:Math.round(score*100.0/total),"history",progress.findTop20ByStudentNameOrderByCompletedAtDesc(identity).stream().map(this::progressDto).toList());}
 @Transactional(readOnly=true) @GetMapping("/extracurricular/progress") public Map<String,Object> getExtracurricularProgress(@RequestHeader("Authorization") String authorization){StudentAccount student=auth.requireSession(bearer(authorization));List<ExtracurricularRecord> records=extracurricularRecords.findByStudent_Id(student.getId());List<String> interests=records.stream().filter(r->"INTEREST".equals(r.getRecordType())).map(ExtracurricularRecord::getRecordKey).toList();Map<String,String> completed=new LinkedHashMap<>();records.stream().filter(r->"COMPLETED".equals(r.getRecordType())).forEach(r->completed.put(r.getRecordKey(),r.getCompletedAt()==null?java.time.Instant.now().toString():r.getCompletedAt().toString()));return Map.of("interests",interests,"completed",completed);}
 @Transactional @PutMapping("/extracurricular/progress") public Map<String,Object> saveExtracurricularProgress(@RequestHeader("Authorization") String authorization,@Valid @RequestBody ExtracurricularStateRequest req){StudentAccount student=auth.requireSession(bearer(authorization));if(req.interests().size()>20||req.completed().size()>200)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Jumlah kegiatan melebihi batas.");if(!CLUB_IDS.containsAll(req.interests())||!ACTIVITY_IDS.containsAll(req.completed().keySet()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Kegiatan ekskul tidak dikenal.");List<ExtracurricularRecord> records=new ArrayList<>();req.interests().stream().distinct().forEach(key->records.add(new ExtracurricularRecord(student,key,"INTEREST",null)));req.completed().keySet().forEach(key->records.add(new ExtracurricularRecord(student,key,"COMPLETED",java.time.Instant.now())));extracurricularRecords.deleteByStudent_Id(student.getId());extracurricularRecords.saveAll(records);return getExtracurricularProgress(authorization);}
 @Transactional(readOnly=true) @GetMapping("/admin/students") public List<Map<String,Object>> getStudentMonitoring(@RequestHeader("Authorization") String authorization){requireAdmin(authorization);return accounts.findByRoleOrderByIdAsc("STUDENT").stream().<Map<String,Object>>map(student->{List<Progress> items=progress.findByStudentName(accountIdentity(student));int score=items.stream().mapToInt(Progress::getScore).sum();int total=items.stream().mapToInt(Progress::getTotal).sum();var dto=new LinkedHashMap<String,Object>();dto.put("id",student.getId());dto.put("name",student.getName());dto.put("username",student.getUsername());dto.put("email",student.getEmail());dto.put("grade",student.getGrade());dto.put("completedQuizzes",items.size());dto.put("averagePercent",total==0?0:Math.round(score*100.0/total));dto.put("correctAnswers",score);dto.put("wrongAnswers",total-score);dto.put("history",items.stream().sorted(Comparator.comparing(Progress::getCompletedAt).reversed()).limit(20).map(this::progressDto).toList());return dto;}).toList();}
 @Transactional(readOnly=true) @GetMapping("/admin/curriculum") public Map<String,Object> getCurriculumCatalog(@RequestHeader("Authorization") String authorization){requireAdmin(authorization);return Map.of("catalog",curriculumMonitor.catalog(),"officialCatalogUrl","https://buku.kemendikdasmen.go.id/katalog/");}
 @GetMapping("/admin/ai-questions") public Map<String,Object> getAiQuestionStatus(@RequestHeader("Authorization") String authorization){requireAdmin(authorization);return aiQuestionScheduler.status();}
 @PostMapping("/admin/curriculum/check") public List<Map<String,Object>> checkCurriculumSources(@RequestHeader("Authorization") String authorization){requireAdmin(authorization);return curriculumMonitor.checkAll();}
 @Transactional @PostMapping("/admin/curriculum/{sourceKey}/acknowledge") public Map<String,Object> acknowledgeCurriculumSource(@RequestHeader("Authorization") String authorization,@PathVariable String sourceKey){requireAdmin(authorization);return curriculumMonitor.acknowledge(sourceKey);}
 @Transactional(readOnly=true) @GetMapping("/admin/students/{id}") public Map<String,Object> getStudentDetail(@RequestHeader("Authorization") String authorization,@PathVariable Long id){requireAdmin(authorization);StudentAccount student=accounts.findById(id).filter(a->a.getRole().equals("STUDENT")).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Siswa tidak ditemukan"));List<Progress> items=progress.findByStudentName(accountIdentity(student));var dto=new LinkedHashMap<String,Object>(auth.profile(student));dto.put("completedQuizzes",items.size());dto.put("history",items.stream().sorted(Comparator.comparing(Progress::getCompletedAt).reversed()).limit(20).map(this::progressDto).toList());return dto;}
 @Transactional @DeleteMapping("/admin/students/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void deleteStudent(@RequestHeader("Authorization") String authorization,@PathVariable Long id){requireAdmin(authorization);StudentAccount student=accounts.findById(id).filter(a->"STUDENT".equals(a.getRole())).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Siswa tidak ditemukan"));progress.deleteByStudentName(accountIdentity(student));extracurricularRecords.deleteByStudent_Id(student.getId());accounts.delete(student);}
 private String accountIdentity(StudentAccount account){return "akun-"+account.getId();}
 private boolean isAdmin(StudentAccount account){return "ADMIN".equals(account.getRole());}
 private String viewGrade(StudentAccount account,String requestedGrade){if(requestedGrade==null||!isAdmin(account))return account.getGrade();if(!requestedGrade.matches("[1-6]"))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Pilih kelas 1 sampai 6.");return requestedGrade;}
 private void requireAdmin(String authorization){StudentAccount account=auth.requireSession(bearer(authorization));if(!isAdmin(account))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Akses khusus admin.");}
 @PostMapping("/lessons/{id}/check") public Map<String,Object> checkAnswer(@PathVariable Long id,@RequestHeader("Authorization") String authorization,@Valid @RequestBody AnswerRequest req){Lesson lesson=lessons.findByIdWithSubject(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Materi tidak ditemukan"));requireLessonGrade(lesson,authorization);Question q=questions.findByIdAndLessonId(req.questionId(),id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Soal tidak ditemukan"));String correctOption=ArabicOptionText.render(lesson,q.getOptions()[q.getCorrectOptionIndex()]);boolean correct=correctOption.equals(req.selectedOptionText());return Map.of("correct",correct,"correctOption",correctOption,"explanation",q.getExplanation());}
 private List<String> shuffledOptions(Question question){List<String> options=new ArrayList<>(Arrays.asList(question.getOptions()));Collections.shuffle(options,QUESTION_RANDOM);return options;}
 private String bearer(String authorization){if(authorization==null||!authorization.startsWith("Bearer "))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Silakan masuk terlebih dahulu.");return authorization.substring(7);}
 private String gradeNumber(String grade){java.util.regex.Matcher m=java.util.regex.Pattern.compile("\\d+").matcher(grade);return m.find()?m.group():"";}
 private int chapterNumber(String title){java.util.regex.Matcher m=java.util.regex.Pattern.compile("(?i)^Bab\\s+(\\d+)").matcher(title);return m.find()?Integer.parseInt(m.group(1)):Integer.MAX_VALUE;}
 private boolean isChapterTitle(String title){return title!=null&&title.matches("(?i)^Bab\\s+\\d+\\s*[—–-].*");}
 private void requireLessonGrade(Lesson lesson,String authorization){StudentAccount account=auth.requireSession(bearer(authorization));if(isAdmin(account))return;String grade=account.getGrade();if(!gradeNumber(lesson.getGrade()).equals(grade))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Materi ini tidak sesuai dengan kelas akunmu.");}
 private Map<String,Object> lessonDto(Lesson l){var m=new LinkedHashMap<String,Object>();m.put("id",l.getId());m.put("subjectId",l.getSubject().getId());m.put("subjectName",l.getSubject().getName());m.put("title",l.getTitle());m.put("grade",l.getGrade());m.put("content",l.getContent());m.put("estimatedMinutes",l.getEstimatedMinutes());return m;}
 private Map<String,Object> progressDto(Progress p){var m=new LinkedHashMap<String,Object>();m.put("id",p.getId());m.put("studentName",p.getStudentName());m.put("lessonId",p.getLesson().getId());m.put("lessonTitle",p.getLesson().getTitle());m.put("subjectName",p.getLesson().getSubject().getName());m.put("score",p.getScore());m.put("total",p.getTotal());m.put("percent",p.getTotal()==0?0:Math.round(p.getScore()*100.0/p.getTotal()));m.put("completedAt",p.getCompletedAt());return m;}
 public record ProgressRequest(@NotBlank @Size(max=80) String studentName,@NotNull Long lessonId,@NotNull @Min(0) Integer score,@NotNull @Min(1) @Max(100) Integer total){}
 public record ExtracurricularStateRequest(@NotNull @Size(max=20) List<@NotBlank @Pattern(regexp="[a-z]+") String> interests,@NotNull @Size(max=200) Map<@NotBlank @Pattern(regexp="[a-z]+:[a-z]+") String,@NotBlank @Size(max=80) String> completed){}
 public record AnswerRequest(@NotNull Long questionId,@NotBlank @Size(max=2000) String selectedOptionText){}
}
